import assert from "node:assert/strict";
import { chmod, mkdtemp, readFile, readdir, rm, stat, utimes, writeFile } from "node:fs/promises";
import { randomUUID } from "node:crypto";
import os from "node:os";
import path from "node:path";
import test from "node:test";
import {
  AuthServiceError,
  publicAccountLabelFromAuth,
  safeAuthUrl,
  YishuAuthService,
  type AuthModelRuntime,
  type AuthServiceEvent,
} from "../src/auth-service.js";
import { InMemoryCredentialStore, ProductCredentialStore, resolveYishuAuthPath } from "../src/auth-store.js";
import { runAuthWatchdog } from "../src/auth-watchdog.js";
import { authPublicStatusSchema, sanitizePublicAccountLabel } from "../src/auth-protocol.js";

function unsignedJwt(claims: Record<string, unknown>): string {
  const header = Buffer.from(JSON.stringify({ alg: "none", typ: "JWT" })).toString("base64url");
  const payload = Buffer.from(JSON.stringify(claims)).toString("base64url");
  return `${header}.${payload}.sig`;
}

class FakeOAuthRuntime implements AuthModelRuntime {
  configured = false;
  interaction?: Parameters<AuthModelRuntime["login"]>[2];

  getProvider(providerId: string) {
    return { id: providerId, auth: { oauth: {} } };
  }

  async getAvailable(providerId: string) {
    if (!this.configured) return [];
    return providerId === "xai"
      ? [
          { id: "grok-4.3", name: "Grok 4.3", provider: "xai" },
          { id: "grok-4.5", name: "Grok 4.5", provider: "xai" },
          { id: "grok-build-0.1", name: "Grok Build", provider: "xai" },
        ]
      : [{ id: "gpt-5.4", name: "GPT-5.4", provider: "openai-codex" }];
  }

  async checkAuth() {
    return this.configured ? { type: "oauth" as const } : undefined;
  }

  async getAuth() {
    return this.configured ? { auth: { headers: { "x-test": "discard" } } } : undefined;
  }

  async login(_providerId: string, _type: "oauth", interaction: Parameters<AuthModelRuntime["login"]>[2]) {
    this.interaction = interaction;
    interaction.notify({ type: "auth_url", url: "https://auth.example.test/authorize?code_challenge=public" });
    const code = await interaction.prompt({ type: "manual_code", message: "Paste the one-time code." });
    assert.equal(code, "one-time-code");
    this.configured = true;
    // Deliberately return credential-shaped data; AuthService must never copy
    // any of these fields into a public event.
    return {
      type: "oauth",
      access: "ACCESS_VALUE_SHOULD_NOT_CROSS_WIRE",
      refresh: "REFRESH_VALUE_SHOULD_NOT_CROSS_WIRE",
      expires: Date.now() + 60_000,
      accountId: "ACCOUNT_ID_SHOULD_NOT_CROSS_WIRE",
    };
  }

  async logout() {
    this.configured = false;
  }
}

function waitForEvent(events: AuthServiceEvent[], type: AuthServiceEvent["type"]): Promise<AuthServiceEvent> {
  const existing = events.find((event) => event.type === type);
  if (existing) return Promise.resolve(existing);
  return new Promise((resolve) => {
    const timer = setInterval(() => {
      const event = events.find((candidate) => candidate.type === type);
      if (!event) return;
      clearInterval(timer);
      resolve(event);
    }, 1);
  });
}

test("OpenAI browser authorization URL crosses the product boundary", () => {
  const url = "https://auth.openai.com/oauth/authorize"
    + "?response_type=code"
    + "&client_id=public-client"
    + "&redirect_uri=http%3A%2F%2Flocalhost%3A1455%2Fauth%2Fcallback"
    + "&code_challenge=public-challenge"
    + "&id_token_add_organizations=true"
    + "&state=public-state";

  assert.equal(safeAuthUrl(url), url);
});

test("OAuth callback results and credentials never cross the product boundary", () => {
  assert.equal(safeAuthUrl("https://example.test/callback?code=secret-code"), undefined);
  assert.equal(safeAuthUrl("https://example.test/callback#access_token=secret-token"), undefined);
  assert.equal(
    safeAuthUrl("https://example.test/authorize?value=eyJaaaaaaaaaaaaaaaaaaaa.bbbbbbbbbb.cccccccccc"),
    undefined,
  );
});

test("public account labels keep email and drop tokens or account ids", () => {
  assert.equal(sanitizePublicAccountLabel("you@example.com"), "you@example.com");
  assert.equal(sanitizePublicAccountLabel("ACCOUNT_ID_SHOULD_NOT_CROSS_WIRE"), undefined);
  assert.equal(sanitizePublicAccountLabel("acct_secret"), undefined);
  assert.equal(sanitizePublicAccountLabel("eyJaaaaaaaaaaaaaaaaaaaa.bbbbbbbbbb.cccccccccc"), undefined);
  assert.equal(
    publicAccountLabelFromAuth({
      apiKey: unsignedJwt({
        email: "you@example.com",
        "https://api.openai.com/auth": { chatgpt_account_id: "ACCOUNT_ID_SHOULD_NOT_CROSS_WIRE" },
      }),
      accountId: "ACCOUNT_ID_SHOULD_NOT_CROSS_WIRE",
    }),
    "you@example.com",
  );
  assert.equal(
    publicAccountLabelFromAuth({
      apiKey: unsignedJwt({
        "https://api.openai.com/auth": { chatgpt_account_id: "ACCOUNT_ID_SHOULD_NOT_CROSS_WIRE" },
      }),
      accountId: "ACCOUNT_ID_SHOULD_NOT_CROSS_WIRE",
    }),
    undefined,
  );
});

test("OAuth status exposes a public account label without credential material", async () => {
  const runtime = new FakeOAuthRuntime();
  runtime.configured = true;
  runtime.getAuth = async () => ({
    apiKey: unsignedJwt({
      email: "you@example.com",
      "https://api.openai.com/auth": { chatgpt_account_id: "ACCOUNT_ID_SHOULD_NOT_CROSS_WIRE" },
    }),
    accountId: "ACCOUNT_ID_SHOULD_NOT_CROSS_WIRE",
  });
  const service = new YishuAuthService(Promise.resolve(runtime));

  const [status] = await service.status("openai-codex");
  assert.ok(status);
  assert.equal(status.accountLabel, "you@example.com");
  assert.doesNotMatch(JSON.stringify(status), /ACCESS_VALUE|REFRESH_VALUE|ACCOUNT_ID|eyJ/);
  assert.deepEqual(authPublicStatusSchema.parse(status), status);
});

test("OAuth status exposes only controlled models and marks xAI experimental", async () => {
  const runtime = new FakeOAuthRuntime();
  runtime.configured = true;
  const service = new YishuAuthService(Promise.resolve(runtime));

  const [status] = await service.status("xai");
  assert.ok(status);
  assert.deepEqual(status.models.map((model) => model.id), ["grok-4.3", "grok-4.5", "grok-build-0.1"]);
  assert.equal(status.experimental, "experimental_local_subscription");
  assert.equal(status.authType, "oauth");
  assert.equal(status.configured, true);
  assert.doesNotMatch(JSON.stringify(status), /ACCESS_VALUE|REFRESH_VALUE|ACCOUNT_ID/);
  assert.deepEqual(authPublicStatusSchema.parse(status), status);
});

test("ambient API-key-only state is not reported as subscription OAuth", async () => {
  const runtime = new FakeOAuthRuntime();
  runtime.getProvider = (providerId: string) => ({ id: providerId, auth: { apiKey: {} } });
  runtime.checkAuth = async () => ({ type: "api_key" as const });
  const service = new YishuAuthService(Promise.resolve(runtime));

  const [status] = await service.status("xai");
  assert.equal(status?.configured, false);
  assert.deepEqual(status?.models, []);
});

test("login interaction emits prompt/completion without credential material", async () => {
  const runtime = new FakeOAuthRuntime();
  const service = new YishuAuthService(Promise.resolve(runtime));
  const events: AuthServiceEvent[] = [];
  const login = service.startLogin(
    { requestId: "b3a7a0f4-68bf-4d05-b9a5-2b08dc8b7ea1", traceId: "3b73e4d1-0c48-4936-b4c4-b7a4a770cd61" },
    "xai",
    (event) => events.push(event),
  );

  const promptEvent = await waitForEvent(events, "auth.prompt");
  assert.equal(promptEvent.type, "auth.prompt");
  if (promptEvent.type !== "auth.prompt") throw new Error("prompt event missing");
  assert.equal(service.replyPrompt(
    "b3a7a0f4-68bf-4d05-b9a5-2b08dc8b7ea1",
    "xai",
    promptEvent.payload.promptId,
    "one-time-code",
  ), true);
  await login;

  assert.ok(events.some((event) => event.type === "auth.url"));
  const completed = events.find((event) => event.type === "auth.completed");
  assert.ok(completed);
  const wire = JSON.stringify(events);
  assert.doesNotMatch(wire, /ACCESS_VALUE|REFRESH_VALUE|ACCOUNT_ID/);
  assert.match(wire, /grok-4\.3/);
});

test("Pi auth info, progress, and instructions redact account and token markers", async () => {
  const runtime = new FakeOAuthRuntime();
  runtime.login = async (_providerId, _type, interaction) => {
    interaction.notify({
      type: "info",
      message: "account_id=acct-secret credential=credential-secret token=plain-secret secret=plain-secret",
    });
    interaction.notify({ type: "progress", message: "Authorization: Bearer bearer-secret" });
    interaction.notify({
      type: "auth_url",
      url: "https://auth.example.test/authorize?code_challenge=public",
      instructions: "client_secret=client-secret",
    });
    const code = await interaction.prompt({ type: "manual_code", message: "Paste the one-time code." });
    assert.equal(code, "one-time-code");
    runtime.configured = true;
  };
  const service = new YishuAuthService(Promise.resolve(runtime));
  const events: AuthServiceEvent[] = [];
  const login = service.startLogin(
    { requestId: "5cc3c4c1-68f8-4b2f-9a2d-94b1d9b0e0c2", traceId: "6ca7e3ad-9e6b-4cc9-a5e7-5d58b9cc75cd" },
    "xai",
    (event) => events.push(event),
  );
  const promptEvent = await waitForEvent(events, "auth.prompt");
  if (promptEvent.type !== "auth.prompt") throw new Error("prompt event missing");
  assert.equal(service.replyPrompt(
    "5cc3c4c1-68f8-4b2f-9a2d-94b1d9b0e0c2",
    "xai",
    promptEvent.payload.promptId,
    "one-time-code",
  ), true);
  await login;
  const wire = JSON.stringify(events);
  assert.doesNotMatch(wire, /acct-secret|credential-secret|plain-secret|bearer-secret|client-secret/);
  assert.match(wire, /请按提示完成登录|正在完成登录/);
});

test("cancel aborts the pending OAuth prompt and emits a typed failure", async () => {
  const runtime = new FakeOAuthRuntime();
  const service = new YishuAuthService(Promise.resolve(runtime));
  const events: AuthServiceEvent[] = [];
  const login = service.startLogin(
    { requestId: "f1eeb04e-1fa0-42a0-a4d5-8a7d2dbf0cdf", traceId: "0f8d74e4-9f15-42cf-86d7-e9f1b5d91f2f" },
    "openai-codex",
    (event) => events.push(event),
  );
  await waitForEvent(events, "auth.prompt");
  assert.equal(service.cancelLogin("f1eeb04e-1fa0-42a0-a4d5-8a7d2dbf0cdf", "openai-codex"), true);
  await login;
  const failed = events.find((event) => event.type === "auth.failed");
  assert.ok(failed);
  if (failed?.type === "auth.failed") assert.equal(failed.payload.code, "cancelled");
});

test("an existing usable OAuth account requires logout before account switching", async () => {
  const runtime = new FakeOAuthRuntime();
  runtime.configured = true;
  const service = new YishuAuthService(Promise.resolve(runtime));
  const events: AuthServiceEvent[] = [];
  await service.startLogin(
    { requestId: "56f79091-4f08-4640-8ce2-d28b625e6e2e", traceId: "0c27f1d4-8c9b-4b7c-8791-6f6e0b3c47d6" },
    "xai",
    (event) => events.push(event),
  );
  const failed = events.find((event) => event.type === "auth.failed");
  assert.equal(failed?.payload.code, "invalid_request");
  assert.equal(runtime.configured, true, "A must remain configured until explicit logout");
});

test("cancel after a provider ignores AbortSignal cannot emit completed or retain its credential", async () => {
  const runtime = new FakeOAuthRuntime();
  runtime.login = async () => {
    await new Promise<void>((resolve) => setTimeout(resolve, 15));
    runtime.configured = true;
    return {
      type: "oauth",
      access: "CANCELLED_ACCESS_VALUE",
      refresh: "CANCELLED_REFRESH_VALUE",
      expires: Date.now() + 60_000,
    };
  };
  const service = new YishuAuthService(Promise.resolve(runtime));
  const events: AuthServiceEvent[] = [];
  const login = service.startLogin(
    { requestId: "89d4e7b2-43ae-49f7-b38c-042711a4b1b2", traceId: "d1e87198-23e8-4709-bc94-bf3b80cec29a" },
    "xai",
    (event) => events.push(event),
  );
  assert.equal(service.cancelLogin("89d4e7b2-43ae-49f7-b38c-042711a4b1b2", "xai"), true);
  await login;
  assert.equal(events.some((event) => event.type === "auth.completed"), false);
  assert.equal(events.find((event) => event.type === "auth.failed")?.payload.code, "cancelled");
  assert.equal(runtime.configured, false);
});

test("one provider cannot run two OAuth logins concurrently", async () => {
  const runtime = new FakeOAuthRuntime();
  const service = new YishuAuthService(Promise.resolve(runtime));
  const firstEvents: AuthServiceEvent[] = [];
  const secondEvents: AuthServiceEvent[] = [];
  const first = service.startLogin(
    { requestId: "aafcc8e9-f70e-4b43-a6e6-e7d15f35a10a", traceId: "7b980fab-5f98-4daa-b7d3-eab468bd4d5f" },
    "xai",
    (event) => firstEvents.push(event),
  );
  const second = service.startLogin(
    { requestId: "da53cdb4-e3be-41f6-9758-b4c9b5f8bca5", traceId: "a1ac8c88-0af6-4382-9a2e-fae83204f64c" },
    "xai",
    (event) => secondEvents.push(event),
  );
  await second;
  assert.equal(secondEvents.find((event) => event.type === "auth.failed")?.payload.code, "invalid_request");
  assert.equal(service.cancelLogin("aafcc8e9-f70e-4b43-a6e6-e7d15f35a10a", "xai"), true);
  await first;
  assert.ok(firstEvents.some((event) => event.type === "auth.failed"));
});

test("logout waits for a late login completion before removing credentials", async () => {
  const runtime = new FakeOAuthRuntime();
  runtime.login = async () => {
    await new Promise<void>((resolve) => setTimeout(resolve, 15));
    // Simulate a provider that finishes one final poll after cancellation.
    runtime.configured = true;
    return {
      type: "oauth",
      access: "LATE_ACCESS_VALUE",
      refresh: "LATE_REFRESH_VALUE",
      expires: Date.now() + 60_000,
    };
  };
  const service = new YishuAuthService(Promise.resolve(runtime));
  const loginEvents: AuthServiceEvent[] = [];
  const logoutEvents: AuthServiceEvent[] = [];
  const login = service.startLogin(
    { requestId: "4b3fb063-20ee-4a4d-ab55-0e6e9e65f51d", traceId: "49ca857b-8f25-43c4-8ba7-31dba2750d49" },
    "xai",
    (event) => loginEvents.push(event),
  );
  const logout = service.logout(
    { requestId: "dcb5207d-815d-4265-923c-37fba1fcc7aa", traceId: "63f8f4af-5dbe-4562-8faf-8a3df2dc779a" },
    "xai",
    (event) => logoutEvents.push(event),
  );
  await Promise.all([login, logout]);
  assert.equal(loginEvents.some((event) => event.type === "auth.completed"), false);
  assert.equal(runtime.configured, false, "late login must not revive credentials after logout");
  assert.ok(logoutEvents.some((event) => event.type === "auth.logged_out"));
  assert.doesNotMatch(JSON.stringify(logoutEvents), /LATE_ACCESS|LATE_REFRESH/);
});

test("status reports credential storage failures as typed terminal errors", async () => {
  const runtime = new FakeOAuthRuntime();
  runtime.checkAuth = async () => {
    throw new Error("credential store permission denied");
  };
  const service = new YishuAuthService(Promise.resolve(runtime));
  await assert.rejects(service.status("xai"), (error: unknown) => {
    assert.ok(error instanceof AuthServiceError);
    assert.equal(error.code, "storage_failed");
    assert.doesNotMatch(error.message, /auth\.json|permission/);
    return true;
  });
});

test("product credential store uses Yishu path and restrictive permissions", async () => {
  const tempDirectory = await mkdtemp(path.join(os.tmpdir(), "yishu-auth-test-"));
  const authPath = path.join(tempDirectory, "Auth", "auth.json");
  try {
    const store = new ProductCredentialStore(authPath);
    await store.modify("xai", async () => ({
      type: "oauth",
      access: "ACCESS_TEST_ONLY",
      refresh: "REFRESH_TEST_ONLY",
      expires: Date.now() + 60_000,
    }));
    const directoryMode = (await stat(path.dirname(authPath))).mode & 0o777;
    const fileMode = (await stat(authPath)).mode & 0o777;
    assert.equal(directoryMode, 0o700);
    assert.equal(fileMode, 0o600);
    assert.deepEqual(await store.list(), [{ providerId: "xai", type: "oauth" }]);
    assert.match(await readFile(authPath, "utf8"), /"type": "oauth"/);
  } finally {
    await rm(tempDirectory, { recursive: true, force: true });
  }
  assert.match(resolveYishuAuthPath("/tmp/yishu-home"), /Library\/Application Support\/Yishu\/Auth\/auth\.json$/);
  const memory = new InMemoryCredentialStore();
  assert.deepEqual(await memory.list(), []);
});

test("product credential store removes only old restrictive auth temp files after locking", async () => {
  const tempDirectory = await mkdtemp(path.join(os.tmpdir(), "yishu-auth-temp-test-"));
  const authPath = path.join(tempDirectory, "Auth", "auth.json");
  try {
    const store = new ProductCredentialStore({
      authPath,
      lockStaleMs: 30,
      lockWaitMs: 500,
      lockHeartbeatMs: 10,
    });
    await store.modify("xai", async () => ({
      type: "oauth",
      access: "ACCESS_TEMP_TEST",
      refresh: "REFRESH_TEMP_TEST",
      expires: Date.now() + 60_000,
    }));

    const staleTempPath = `${authPath}.${process.pid}.${randomUUID()}.tmp`;
    await writeFile(staleTempPath, "credential-shaped temp content", { mode: 0o600 });
    await chmod(staleTempPath, 0o600);
    const old = new Date(Date.now() - 500);
    await utimes(staleTempPath, old, old);
    await store.modify("xai", async (current) => current);

    const entries = await readdir(path.dirname(authPath));
    assert.equal(entries.includes(path.basename(staleTempPath)), false);
  } finally {
    await rm(tempDirectory, { recursive: true, force: true });
  }
});

test("active auth lock heartbeat prevents a slow refresh from being reclaimed", async () => {
  const tempDirectory = await mkdtemp(path.join(os.tmpdir(), "yishu-auth-lock-test-"));
  const authPath = path.join(tempDirectory, "Auth", "auth.json");
  let releaseCallback!: () => void;
  const callbackReleased = new Promise<void>((resolve) => { releaseCallback = resolve; });
  let lockHeld!: () => void;
  const lockStarted = new Promise<void>((resolve) => { lockHeld = resolve; });
  try {
    const options = { authPath, lockStaleMs: 30, lockWaitMs: 90, lockHeartbeatMs: 8 };
    const firstStore = new ProductCredentialStore(options);
    const secondStore = new ProductCredentialStore(options);
    const first = firstStore.modify("xai", async () => {
      lockHeld();
      await callbackReleased;
      return {
        type: "oauth" as const,
        access: "ACCESS_LOCK_TEST",
        refresh: "REFRESH_LOCK_TEST",
        expires: Date.now() + 60_000,
      };
    });
    await lockStarted;

    const lockPath = `${authPath}.lock`;
    const before = (await stat(lockPath)).mtimeMs;
    await new Promise<void>((resolve) => setTimeout(resolve, 55));
    const after = (await stat(lockPath)).mtimeMs;
    assert.ok(after > before, "the lock mtime should be refreshed while callback is running");

    await assert.rejects(
      secondStore.modify("xai", async () => ({
        type: "oauth",
        access: "SHOULD_NOT_WRITE",
        refresh: "SHOULD_NOT_WRITE",
        expires: Date.now() + 60_000,
      })),
      /Auth storage is busy/,
    );
    releaseCallback();
    await first;
  } finally {
    releaseCallback?.();
    await rm(tempDirectory, { recursive: true, force: true });
  }
});

test("auth status watchdog emits one timeout and consumes a late result", async () => {
  let resolveStatus!: () => void;
  const statusOperation = new Promise<void>((resolve) => { resolveStatus = resolve; });
  const events: string[] = [];
  const result = await runAuthWatchdog(statusOperation, 10, () => events.push("timeout"));
  assert.deepEqual(result, { timedOut: true });
  resolveStatus();
  await new Promise<void>((resolve) => setImmediate(resolve));
  assert.deepEqual(events, ["timeout"]);
});

test("logout watchdog keeps the provider transition until late cleanup settles", async () => {
  const runtime = new FakeOAuthRuntime();
  runtime.configured = true;
  let resolveLogout!: () => void;
  runtime.logout = async () => {
    await new Promise<void>((resolve) => { resolveLogout = resolve; });
    runtime.configured = false;
  };
  const service = new YishuAuthService(Promise.resolve(runtime));
  let emitAllowed = true;
  const visibleEvents: AuthServiceEvent[] = [];
  const logout = service.logout(
    { requestId: "bde20c5a-1c4f-4d20-a889-5470514d55ee", traceId: "630f026b-9e4a-4fd7-9e34-73c1d2377fa8" },
    "xai",
    (event) => {
      if (emitAllowed) visibleEvents.push(event);
    },
  );
  const result = await runAuthWatchdog(logout, 10, () => { emitAllowed = false; });
  assert.deepEqual(result, { timedOut: true });

  const loginEvents: AuthServiceEvent[] = [];
  await service.startLogin(
    { requestId: "5b90357d-1e9e-4c64-99f3-4ecaf2df2c5a", traceId: "edbbf211-a5b5-4599-80af-ae976b26d94e" },
    "xai",
    (event) => loginEvents.push(event),
  );
  assert.equal(loginEvents.find((event) => event.type === "auth.failed")?.payload.code, "invalid_request");

  resolveLogout();
  await logout;
  assert.equal(visibleEvents.some((event) => event.type === "auth.logged_out"), false);
});

import { randomUUID } from "node:crypto";
import {
  AUTH_CONTROLLED_MODEL_IDS,
  AUTH_PROVIDER_IDS,
  sanitizePublicAccountLabel,
  type AuthDeviceCodePayload,
  type AuthFailureCode,
  type AuthFailurePayload,
  type AuthInfoPayload,
  type AuthProgressPayload,
  type AuthPrompt,
  type AuthPromptPayload,
  type AuthProviderId,
  type AuthPublicModel,
  type AuthPublicStatus,
  type AuthUrlPayload,
} from "./auth-protocol.js";

type PiAuthPrompt = AuthPrompt & { signal?: AbortSignal };
type PiAuthEvent =
  | { type: "info"; message: string; links?: readonly { url: string; label?: string }[] }
  | { type: "auth_url"; url: string; instructions?: string }
  | { type: "device_code"; userCode: string; verificationUri: string; intervalSeconds?: number; expiresInSeconds?: number }
  | { type: "progress"; message: string };

export interface AuthInteraction {
  signal?: AbortSignal;
  prompt(prompt: PiAuthPrompt): Promise<string>;
  notify(event: PiAuthEvent): void;
}

interface AuthModelLike {
  id: string;
  name?: string;
  provider?: string;
}

interface AuthProviderLike {
  id: string;
  auth?: {
    oauth?: unknown;
    apiKey?: unknown;
  };
}

/** Structural subset makes AuthService straightforward to test without login/network. */
export interface AuthModelRuntime {
  getProvider(providerId: string): AuthProviderLike | undefined;
  getAvailable(providerId: string): Promise<readonly AuthModelLike[]>;
  checkAuth(providerId: string): Promise<{ type: "api_key" | "oauth" } | undefined>;
  getAuth(providerId: string): Promise<unknown>;
  login(providerId: string, type: "oauth", interaction: AuthInteraction): Promise<unknown>;
  logout(providerId: string): Promise<void>;
}

export type AuthTransitionKind = "login" | "logout" | "relogin_required";

export class AuthServiceError extends Error {
  constructor(readonly code: AuthFailureCode, message: string) {
    super(message);
    this.name = "AuthServiceError";
  }
}

/** Runtime-owned barrier for dropping old provider sessions before credentials change. */
export interface AuthTransitionHooks {
  beginProviderTransition?(provider: AuthProviderId, kind: AuthTransitionKind): Promise<void>;
  endProviderTransition?(provider: AuthProviderId, kind: AuthTransitionKind): void;
}

export type AuthServiceEvent =
  | { type: "auth.status"; payload: AuthPublicStatus }
  | { type: "auth.prompt"; payload: AuthPromptPayload }
  | { type: "auth.info"; payload: AuthInfoPayload }
  | { type: "auth.url"; payload: AuthUrlPayload }
  | { type: "auth.device_code"; payload: AuthDeviceCodePayload }
  | { type: "auth.progress"; payload: AuthProgressPayload }
  | { type: "auth.completed"; payload: AuthPublicStatus }
  | { type: "auth.failed"; payload: AuthFailurePayload }
  | { type: "auth.logged_out"; payload: AuthPublicStatus };

export interface AuthRequestContext {
  requestId: string;
  traceId: string;
}

interface PendingPrompt {
  resolve(value: string): void;
  reject(error: Error): void;
  cleanup(): void;
}

interface PendingLogin {
  provider: AuthProviderId;
  abort: AbortController;
  prompts: Map<string, PendingPrompt>;
  settled: Promise<void>;
  settle(): void;
  transitionBegun: boolean;
}

function isAuthProvider(value: string): value is AuthProviderId {
  return (AUTH_PROVIDER_IDS as readonly string[]).includes(value);
}

function isAbortError(error: unknown, signal?: AbortSignal): boolean {
  if (signal?.aborted) return true;
  return error instanceof Error && /cancel|abort/i.test(error.message);
}

function safeText(value: unknown, fallback: string, maxLength = 500): string {
  const text = typeof value === "string" ? value.trim() : "";
  if (!text) return fallback;
  return text.slice(0, maxLength);
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function decodeJwtPayload(token: string): Record<string, unknown> | undefined {
  const parts = token.split(".");
  if (parts.length !== 3) return undefined;
  try {
    const decoded = Buffer.from(parts[1] ?? "", "base64url").toString("utf8");
    const claims: unknown = JSON.parse(decoded);
    return isRecord(claims) ? claims : undefined;
  } catch {
    return undefined;
  }
}

/** Public login name only. Tokens, JWTs, and provider account ids stay off the wire. */
export function publicAccountLabelFromAuth(resolved: unknown): string | undefined {
  if (!isRecord(resolved)) return undefined;
  const direct = sanitizePublicAccountLabel(resolved.email)
    ?? sanitizePublicAccountLabel(resolved.accountLabel);
  if (direct) return direct;
  for (const key of ["id_token", "idToken", "apiKey", "access"] as const) {
    const token = resolved[key];
    if (typeof token !== "string") continue;
    const claims = decodeJwtPayload(token);
    if (!claims) continue;
    const label = sanitizePublicAccountLabel(claims.email)
      ?? sanitizePublicAccountLabel(claims.preferred_username)
      ?? sanitizePublicAccountLabel(claims.name);
    if (label) return label;
  }
  return undefined;
}

const SENSITIVE_MESSAGE_MARKER = /access[_-]?token|refresh[_-]?token|id[_-]?token|api[_-]?key|client[_-]?secret|private[_-]?key|account[_-]?id|credential|authorization|password|secret|bearer|\btoken\b|jwt|\beyJ[a-zA-Z0-9_-]{20,}\.[a-zA-Z0-9_-]{10,}\.[a-zA-Z0-9_-]{10,}\b/i;

function safePublicMessage(value: unknown, fallback: string, maxLength = 500): string {
  const text = safeText(value, fallback, maxLength);
  return SENSITIVE_MESSAGE_MARKER.test(text) ? fallback : text;
}

/** Do not expose OAuth response bodies, bearer values, JWTs, or account ids. */
export function safeRuntimeErrorMessage(error: unknown, fallback = "Pi runtime operation failed."): string {
  const raw = error instanceof Error ? error.message : typeof error === "string" ? error : "";
  if (!raw) return fallback;
  if (
    /access[_-]?token|refresh[_-]?token|id[_-]?token|api[_-]?key|client[_-]?secret|private[_-]?key|password|authorization|bearer|account[_-]?id|credential|secret|\btoken\b|\bjwt\b/i.test(raw)
    || /\beyJ[a-zA-Z0-9_-]{20,}\.[a-zA-Z0-9_-]{10,}\.[a-zA-Z0-9_-]{10,}\b/.test(raw)
  ) {
    return fallback;
  }
  return raw.slice(0, 500);
}

function safeAuthFailure(error: unknown, signal?: AbortSignal): { code: AuthFailureCode; message: string } {
  if (isAbortError(error, signal)) {
    return { code: "cancelled", message: "OAuth 登录已取消。" };
  }
  const raw = error instanceof Error ? error.message : "";
  if (/storage|auth\.json|credential|lock/i.test(raw)) {
    return { code: "storage_failed", message: "登录凭据存储失败，请稍后重试。" };
  }
  if (/relogin|expired|refresh|unauthori[sz]|401/i.test(raw)) {
    return { code: "relogin_required", message: "登录已失效，请重新登录。" };
  }
  return { code: "oauth_failed", message: "OAuth 登录失败，请重试。" };
}

function isStorageError(error: unknown): boolean {
  if (error instanceof AuthServiceError) return error.code === "storage_failed";
  const raw = error instanceof Error ? error.message : typeof error === "string" ? error : "";
  return /auth\.json|credential store|storage|lock|EACCES|EPERM|EISDIR/i.test(raw);
}

export function safeAuthUrl(value: unknown): string | undefined {
  if (typeof value !== "string" || value.length === 0 || value.length > 4096) return undefined;
  // Authorization URLs normally contain state/code_challenge.  A URL carrying
  // a token or a callback code is not safe to put on the wire.
  try {
    const parsed = new URL(value);
    if (parsed.protocol !== "https:") return undefined;
    if (parsed.username || parsed.password) return undefined;
    const sensitiveKey = /^(?:access[_-]?token|refresh[_-]?token|id[_-]?token|token|code|code[_-]?verifier|api[_-]?key|client[_-]?secret|secret|authorization|bearer)$/i;
    const credentialValue = /^(?:bearer\s+)?eyJ[a-zA-Z0-9_-]{20,}\.[a-zA-Z0-9_-]{10,}\.[a-zA-Z0-9_-]{10,}$/i;
    for (const [key, parameterValue] of parsed.searchParams) {
      if (sensitiveKey.test(key)) return undefined;
      if (credentialValue.test(parameterValue)) return undefined;
    }
    const fragment = parsed.hash.startsWith("#") ? parsed.hash.slice(1) : parsed.hash;
    if (fragment) {
      for (const [key, parameterValue] of new URLSearchParams(fragment)) {
        if (sensitiveKey.test(key)) return undefined;
        if (credentialValue.test(parameterValue)) return undefined;
      }
    }
  } catch {
    return undefined;
  }
  return value;
}

function publicPrompt(prompt: PiAuthPrompt): AuthPrompt {
  switch (prompt.type) {
    case "select":
      return {
        type: "select",
        message: safeText(prompt.message, "选择登录方式。"),
        options: prompt.options.slice(0, 16).map((option) => ({
          id: safeText(option.id, "option", 120),
          label: safeText(option.label, "选项", 200),
          ...(option.description ? { description: safeText(option.description, "", 500) } : {}),
        })),
      };
    case "secret":
      return {
        type: "secret",
        message: safeText(prompt.message, "请输入登录信息。"),
        ...(prompt.placeholder ? { placeholder: safeText(prompt.placeholder, "", 200) } : {}),
      };
    case "manual_code":
      return {
        type: "manual_code",
        message: safeText(prompt.message, "请输入授权码。"),
        ...(prompt.placeholder ? { placeholder: safeText(prompt.placeholder, "", 200) } : {}),
      };
    case "text":
      return {
        type: "text",
        message: safeText(prompt.message, "请输入信息。"),
        ...(prompt.placeholder ? { placeholder: safeText(prompt.placeholder, "", 200) } : {}),
      };
  }
}

/**
 * Fail-closed invariant guard for the product-owned provider registry: the
 * subscription providers must never carry an ambient API-key path. The
 * registry is OAuth-only by construction (ADR 0014), so this only asserts
 * that structural property instead of rewriting providers.
 */
export function installProductOAuthProviderPolicy(
  runtime: Pick<AuthModelRuntime, "getProvider">,
): void {
  for (const providerId of AUTH_PROVIDER_IDS) {
    const provider = runtime.getProvider(providerId);
    if (provider?.auth?.apiKey) {
      throw new Error(`Ambient API-key auth must not exist for ${providerId}.`);
    }
  }
}

/** Require an OAuth subscription credential, never an API-key credential. */
export async function requireOAuthSubscriptionAuth(
  runtime: Pick<AuthModelRuntime, "checkAuth" | "getAuth">,
  provider: AuthProviderId,
): Promise<unknown> {
  const check = await runtime.checkAuth(provider);
  if (check?.type !== "oauth") {
    throw new Error(`OAuth is not configured for ${provider}.`);
  }
  const auth = await runtime.getAuth(provider);
  if (!auth) throw new Error(`OAuth is not configured for ${provider}.`);
  return auth;
}

export class YishuAuthService {
  private readonly pending = new Map<string, PendingLogin>();
  /** Serializes login/logout transitions per provider, not just per request. */
  private readonly providerTransitions = new Map<AuthProviderId, AuthTransitionKind>();

  constructor(
    private readonly runtimePromise: Promise<AuthModelRuntime>,
    private readonly hooks: AuthTransitionHooks = {},
  ) {}

  async status(providerId?: AuthProviderId): Promise<readonly AuthPublicStatus[]> {
    const runtime = await this.runtimePromise;
    const providers = providerId ? [providerId] : [...AUTH_PROVIDER_IDS];
    const statuses = await Promise.all(providers.map((provider) => this.statusOne(runtime, provider)));
    for (const status of statuses) {
      if (status.requiresRelogin) await this.reloginRequired(status.provider);
    }
    return statuses;
  }

  async startLogin(
    context: AuthRequestContext,
    provider: AuthProviderId,
    emit: (event: AuthServiceEvent) => void,
  ): Promise<void> {
    if (!isAuthProvider(provider)) {
      emit({
        type: "auth.failed",
        payload: { provider: "xai", code: "invalid_request", message: "不支持的登录提供方。" },
      });
      return;
    }
    if (
      this.pending.has(context.requestId)
      || this.providerTransitions.has(provider)
      || [...this.pending.values()].some((session) => session.provider === provider)
    ) {
      emit({
        type: "auth.failed",
        payload: { provider, code: "invalid_request", message: "已有登录流程正在进行。" },
      });
      return;
    }

    let settle!: () => void;
    const session: PendingLogin = {
      provider,
      abort: new AbortController(),
      prompts: new Map(),
      settled: new Promise<void>((resolve) => { settle = resolve; }),
      settle: () => settle(),
      transitionBegun: false,
    };
    this.providerTransitions.set(provider, "login");
    this.pending.set(context.requestId, session);

    const interaction: AuthInteraction = {
      signal: session.abort.signal,
      prompt: (prompt) => this.waitForPrompt(context, session, prompt, emit),
      notify: (event) => this.forwardPiEvent(provider, event, emit),
    };

    try {
      const runtime = await this.runtimePromise;
      const existingAuth = await runtime.checkAuth(provider);
      if (existingAuth?.type === "oauth") {
        let existingCredentialIsUsable = false;
        try {
          existingCredentialIsUsable = Boolean(await runtime.getAuth(provider));
        } catch {
          // Expired/refresh-failed credentials are the explicit relogin case.
        }
        if (existingCredentialIsUsable) {
          emit({
            type: "auth.failed",
            payload: { provider, code: "invalid_request", message: "请先退出当前账号，再登录其他账号。" },
          });
          return;
        }
      }
      await this.hooks.beginProviderTransition?.(provider, "login");
      session.transitionBegun = true;
      if (existingAuth?.type === "oauth") {
        // A refresh-failed credential is explicitly a relogin path. Remove it
        // before OAuth starts so cancelling cannot delete a still-usable A
        // account or leave a stale credential behind.
        await runtime.logout(provider);
      }
      await runtime.login(provider, "oauth", interaction);
      if (session.abort.signal.aborted) {
        await this.discardCancelledCredential(runtime, provider, emit);
        return;
      }
      const status = (await this.status(provider))[0];
      if (session.abort.signal.aborted) {
        await this.discardCancelledCredential(runtime, provider, emit);
        return;
      }
      if (!status?.configured) {
        emit({
          type: "auth.failed",
          payload: { provider, code: "oauth_failed", message: "登录未完成，请重试。" },
        });
        return;
      }
      emit({ type: "auth.completed", payload: status });
    } catch (error) {
      const runtime = await this.runtimePromise.catch(() => undefined);
      if (session.abort.signal.aborted) {
        if (runtime) await this.discardCancelledCredential(runtime, provider, emit);
        else emit({ type: "auth.failed", payload: { provider, code: "cancelled", message: "OAuth 登录已取消。" } });
      } else {
        const failure = safeAuthFailure(error, session.abort.signal);
        emit({ type: "auth.failed", payload: { provider, ...failure } });
      }
    } finally {
      for (const prompt of session.prompts.values()) {
        prompt.cleanup();
        prompt.reject(new Error("OAuth login cancelled."));
      }
      this.pending.delete(context.requestId);
      session.settle();
      if (this.providerTransitions.get(provider) === "login") {
        this.providerTransitions.delete(provider);
        if (session.transitionBegun) this.hooks.endProviderTransition?.(provider, "login");
      }
    }
  }

  replyPrompt(requestId: string, provider: AuthProviderId, promptId: string, value: string): boolean {
    const session = this.pending.get(requestId);
    const prompt = session?.prompts.get(promptId);
    if (!session || session.provider !== provider || !prompt) return false;
    session.prompts.delete(promptId);
    prompt.cleanup();
    // The value remains transient input to Pi's OAuth flow.  It is never put
    // in an event payload, exception, log, or trace.
    prompt.resolve(value);
    return true;
  }

  cancelLogin(requestId: string, provider: AuthProviderId): boolean {
    const session = this.pending.get(requestId);
    if (!session || session.provider !== provider) return false;
    session.abort.abort();
    return true;
  }

  async logout(
    context: AuthRequestContext,
    provider: AuthProviderId,
    emit: (event: AuthServiceEvent) => void,
  ): Promise<void> {
    const existingTransition = this.providerTransitions.get(provider);
    if (existingTransition === "logout") {
      emit({
        type: "auth.failed",
        payload: { provider, code: "invalid_request", message: "提供方正在切换登录状态。" },
      });
      return;
    }
    this.providerTransitions.set(provider, "logout");
    const pending = [...this.pending.values()].filter((session) => session.provider === provider);
    for (const session of pending) session.abort.abort();
    try {
      // A provider logout must wait for every in-flight login, including a Pi
      // flow that ignores AbortSignal briefly, before deleting credentials.
      await Promise.all(pending.map((session) => session.settled));
      if (!pending.some((session) => session.transitionBegun)) {
        await this.hooks.beginProviderTransition?.(provider, "logout");
      }
      const runtime = await this.runtimePromise;
      await runtime.logout(provider);
      const status = (await this.status(provider))[0];
      if (status) emit({ type: "auth.logged_out", payload: status });
    } catch (error) {
      const failure = safeAuthFailure(error);
      emit({ type: "auth.failed", payload: { provider, ...failure } });
    } finally {
      if (this.providerTransitions.get(provider) === "logout") {
        this.providerTransitions.delete(provider);
        this.hooks.endProviderTransition?.(provider, "logout");
      }
    }
  }

  async reloginRequired(provider: AuthProviderId): Promise<void> {
    if (this.providerTransitions.has(provider)) return;
    this.providerTransitions.set(provider, "relogin_required");
    try {
      await this.hooks.beginProviderTransition?.(provider, "relogin_required");
    } finally {
      if (this.providerTransitions.get(provider) === "relogin_required") {
        this.providerTransitions.delete(provider);
        this.hooks.endProviderTransition?.(provider, "relogin_required");
      }
    }
  }

  private async discardCancelledCredential(
    runtime: AuthModelRuntime,
    provider: AuthProviderId,
    emit: (event: AuthServiceEvent) => void,
  ): Promise<void> {
    try {
      // Pi may return a credential despite AbortSignal. Logout is the only
      // product-owned cleanup path that guarantees it cannot survive cancel.
      await runtime.logout(provider);
      emit({ type: "auth.failed", payload: { provider, code: "cancelled", message: "OAuth 登录已取消。" } });
    } catch (error) {
      const failure = safeAuthFailure(error);
      emit({ type: "auth.failed", payload: { provider, ...failure } });
    }
  }

  private async statusOne(runtime: AuthModelRuntime, provider: AuthProviderId): Promise<AuthPublicStatus> {
    let configured = false;
    let requiresRelogin = false;
    let resolvedAuth: unknown;
    try {
      // checkAuth is provider-scoped and therefore cannot treat an ambient
      // OPENAI_API_KEY/XAI_API_KEY as a subscription after the policy wrapper.
      const check = await runtime.checkAuth(provider);
      configured = check?.type === "oauth";
      if (configured) {
        try {
          // getAuth owns refresh under Pi's credential-store lock.  The
          // credential itself stays here; only a public email/name may leave.
          resolvedAuth = await runtime.getAuth(provider);
          if (!resolvedAuth) {
            configured = false;
            requiresRelogin = true;
          }
        } catch (error) {
          if (isStorageError(error)) throw new AuthServiceError("storage_failed", "登录凭据存储不可用。");
          requiresRelogin = true;
        }
      }
    } catch (error) {
      if (isStorageError(error)) throw new AuthServiceError("storage_failed", "登录凭据存储不可用。");
      requiresRelogin = configured;
    }

    let models: AuthPublicModel[] = [];
    if (configured) {
      try {
        const allowed = new Set<string>(AUTH_CONTROLLED_MODEL_IDS[provider]);
        const available = await runtime.getAvailable(provider);
        models = available
          .filter((model) => allowed.has(model.id))
          .map((model) => ({
            provider,
            id: model.id,
            name: safeText(model.name, model.id, 200),
          }));
      } catch (error) {
        if (isStorageError(error)) throw new AuthServiceError("storage_failed", "登录凭据存储不可用。");
        models = [];
      }
    }

    const accountLabel = configured ? publicAccountLabelFromAuth(resolvedAuth) : undefined;

    return {
      provider,
      configured,
      authType: "oauth",
      models,
      ...(requiresRelogin ? { requiresRelogin: true } : {}),
      ...(accountLabel ? { accountLabel } : {}),
      ...(provider === "xai" ? { experimental: "experimental_local_subscription" as const } : {}),
    };
  }

  private waitForPrompt(
    context: AuthRequestContext,
    session: PendingLogin,
    prompt: PiAuthPrompt,
    emit: (event: AuthServiceEvent) => void,
  ): Promise<string> {
    const promptId = randomUUID();
    return new Promise<string>((resolve, reject) => {
      const onAbort = (): void => {
        session.prompts.delete(promptId);
        cleanup();
        reject(new Error("OAuth login cancelled."));
      };
      const cleanup = (): void => {
        session.abort.signal.removeEventListener("abort", onAbort);
        prompt.signal?.removeEventListener("abort", onAbort);
      };
      session.prompts.set(promptId, { resolve, reject, cleanup });
      session.abort.signal.addEventListener("abort", onAbort, { once: true });
      prompt.signal?.addEventListener("abort", onAbort, { once: true });
      if (session.abort.signal.aborted || prompt.signal?.aborted) {
        onAbort();
        return;
      }
      emit({
        type: "auth.prompt",
        payload: {
          provider: session.provider,
          promptId,
          prompt: publicPrompt(prompt),
        },
      });
    });
  }

  private forwardPiEvent(
    provider: AuthProviderId,
    event: PiAuthEvent,
    emit: (event: AuthServiceEvent) => void,
  ): void {
    if (event.type === "info") {
      const links = event.links
        ?.map((link) => {
          const url = safeAuthUrl(link.url);
          return url ? { url, ...(link.label ? { label: safeText(link.label, "", 200) } : {}) } : undefined;
        })
        .filter((link): link is { url: string; label?: string } => link !== undefined);
      emit({
        type: "auth.info",
        payload: {
          provider,
          message: safePublicMessage(event.message, "请按提示完成登录。"),
          ...(links && links.length > 0 ? { links } : {}),
        },
      });
      return;
    }
    if (event.type === "auth_url") {
      const url = safeAuthUrl(event.url);
      if (!url) {
        emit({ type: "auth.info", payload: { provider, message: "请在登录页面完成授权。" } });
        return;
      }
      emit({
        type: "auth.url",
        payload: {
          provider,
          url,
          ...(event.instructions ? { instructions: safePublicMessage(event.instructions, "请在登录页面完成授权。", 500) } : {}),
        },
      });
      return;
    }
    if (event.type === "device_code") {
      emit({
        type: "auth.device_code",
        payload: {
          provider,
          userCode: safeText(event.userCode, "", 200),
          verificationUri: safeAuthUrl(event.verificationUri) ?? "https://example.invalid/",
          ...(event.intervalSeconds !== undefined ? { intervalSeconds: event.intervalSeconds } : {}),
          ...(event.expiresInSeconds !== undefined ? { expiresInSeconds: event.expiresInSeconds } : {}),
        },
      });
      return;
    }
    emit({
      type: "auth.progress",
      payload: { provider, message: safePublicMessage(event.message, "正在完成登录。") },
    });
  }
}

export function authServiceEventType(event: AuthServiceEvent): AuthServiceEvent["type"] {
  return event.type;
}

import { chmod, mkdir, open, readFile, readdir, rename, rm, stat, utimes, writeFile } from "node:fs/promises";
import { existsSync } from "node:fs";
import os from "node:os";
import path from "node:path";
import { randomUUID } from "node:crypto";

/** The only on-disk credential location owned by this product. */
export function resolveYishuAuthPath(homeDirectory = os.homedir()): string {
  return path.join(homeDirectory, "Library", "Application Support", "Yishu", "Auth", "auth.json");
}

export const YISHU_AUTH_PATH = resolveYishuAuthPath();

/**
 * A local structural copy of pi-ai's Credential types.  Keeping this file
 * independent of pi-ai's private package exports lets the product own its
 * storage contract while still satisfying ModelRuntime's CredentialStore
 * interface.
 */
export type YishuCredential =
  | {
      type: "api_key";
      key?: string;
      env?: Record<string, string>;
    }
  | {
      type: "oauth";
      refresh: string;
      access: string;
      expires: number;
      [key: string]: unknown;
    };

export interface YishuCredentialInfo {
  providerId: string;
  type: YishuCredential["type"];
}

export interface YishuCredentialStore {
  read(providerId: string): Promise<YishuCredential | undefined>;
  list(): Promise<readonly YishuCredentialInfo[]>;
  modify(
    providerId: string,
    fn: (current: YishuCredential | undefined) => Promise<YishuCredential | undefined>,
  ): Promise<YishuCredential | undefined>;
  delete(providerId: string): Promise<void>;
}

type CredentialMap = Record<string, YishuCredential>;

const AUTH_DIRECTORY_MODE = 0o700;
const AUTH_FILE_MODE = 0o600;
const DEFAULT_LOCK_STALE_MS = 30_000;
const DEFAULT_LOCK_WAIT_MS = 10_000;
const DEFAULT_LOCK_HEARTBEAT_MS = 10_000;
const TEMP_FILE_NAME = /^[^/]+\.[0-9]+\.[0-9a-f-]{36}\.tmp$/iu;

export interface ProductCredentialStoreOptions {
  authPath?: string;
  /** Defaults are deliberately conservative; tests can use short values. */
  lockStaleMs?: number;
  lockWaitMs?: number;
  lockHeartbeatMs?: number;
}

interface FileLockOptions {
  staleMs: number;
  waitMs: number;
  heartbeatMs: number;
}

interface LockMetadata {
  ownerId: string;
  pid: number;
  acquiredAt: number;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function parseCredentialMap(content: string | undefined): CredentialMap {
  if (!content?.trim()) return {};
  let parsed: unknown;
  try {
    parsed = JSON.parse(content);
  } catch {
    throw new Error("Auth storage is invalid.");
  }
  if (!isRecord(parsed)) throw new Error("Auth storage is invalid.");

  const result: CredentialMap = {};
  for (const [providerId, value] of Object.entries(parsed)) {
    if (!isRecord(value) || (value.type !== "oauth" && value.type !== "api_key")) {
      throw new Error("Auth storage is invalid.");
    }
    // Preserve Pi's OAuth extension fields (for example account metadata) but
    // reject obviously malformed credentials before they reach ModelRuntime.
    if (value.type === "oauth") {
      if (typeof value.access !== "string" || typeof value.refresh !== "string" || typeof value.expires !== "number") {
        throw new Error("Auth storage is invalid.");
      }
      result[providerId] = value as unknown as YishuCredential;
      continue;
    }
    if (value.key !== undefined && typeof value.key !== "string") {
      throw new Error("Auth storage is invalid.");
    }
    if (value.env !== undefined && (!isRecord(value.env) || Object.values(value.env).some((entry) => typeof entry !== "string"))) {
      throw new Error("Auth storage is invalid.");
    }
    result[providerId] = value as unknown as YishuCredential;
  }
  return result;
}

function serializeCredentialMap(data: CredentialMap): string {
  return JSON.stringify(data, null, 2);
}

async function ensureSecureDirectory(filePath: string): Promise<void> {
  const directory = path.dirname(filePath);
  await mkdir(directory, { recursive: true, mode: AUTH_DIRECTORY_MODE });
  // mkdir's mode is affected by umask and does not repair an existing path.
  await chmod(directory, AUTH_DIRECTORY_MODE);
}

async function readCredentialMap(filePath: string): Promise<CredentialMap> {
  try {
    const content = await readFile(filePath, "utf8");
    return parseCredentialMap(content);
  } catch (error) {
    if (typeof error === "object" && error !== null && "code" in error && error.code === "ENOENT") {
      return {};
    }
    throw error;
  }
}

async function writeCredentialMap(filePath: string, data: CredentialMap): Promise<void> {
  await ensureSecureDirectory(filePath);
  const temporaryPath = `${filePath}.${process.pid}.${randomUUID()}.tmp`;
  try {
    await writeFile(temporaryPath, serializeCredentialMap(data), { encoding: "utf8", mode: AUTH_FILE_MODE });
    await chmod(temporaryPath, AUTH_FILE_MODE);
    await rename(temporaryPath, filePath);
    await chmod(filePath, AUTH_FILE_MODE);
  } finally {
    if (existsSync(temporaryPath)) {
      await rm(temporaryPath, { force: true }).catch(() => undefined);
    }
  }
}

async function readLockMetadata(lockPath: string): Promise<LockMetadata | undefined> {
  try {
    const parsed: unknown = JSON.parse(await readFile(lockPath, "utf8"));
    if (!isRecord(parsed)) return undefined;
    if (typeof parsed.ownerId !== "string" || !parsed.ownerId || typeof parsed.pid !== "number" || !Number.isInteger(parsed.pid)) {
      return undefined;
    }
    return {
      ownerId: parsed.ownerId,
      pid: parsed.pid,
      acquiredAt: typeof parsed.acquiredAt === "number" ? parsed.acquiredAt : 0,
    };
  } catch {
    return undefined;
  }
}

function isProcessAlive(pid: number): boolean {
  if (!Number.isInteger(pid) || pid <= 0) return false;
  try {
    process.kill(pid, 0);
    return true;
  } catch (error) {
    return typeof error === "object" && error !== null && "code" in error && error.code === "EPERM";
  }
}

/** Remove only old auth basename temp files, never arbitrary directory files. */
async function cleanupStaleTemporaryFiles(filePath: string, staleMs: number): Promise<void> {
  const directory = path.dirname(filePath);
  const basename = path.basename(filePath);
  let entries;
  try {
    entries = await readdir(directory, { withFileTypes: true });
  } catch {
    return;
  }
  for (const entry of entries) {
    if (!entry.isFile() || !entry.name.startsWith(`${basename}.`) || !entry.name.endsWith(".tmp") || !TEMP_FILE_NAME.test(entry.name)) {
      continue;
    }
    const temporaryPath = path.join(directory, entry.name);
    try {
      const temporaryStat = await stat(temporaryPath);
      if ((temporaryStat.mode & 0o777) !== AUTH_FILE_MODE) continue;
      if (Date.now() - temporaryStat.mtimeMs <= staleMs) continue;
      await rm(temporaryPath, { force: true });
    } catch {
      // Another process may have cleaned it; do not expose its path/content.
    }
  }
}

type LockRelease = () => Promise<void>;

/**
 * Small cross-process lock matching the semantics needed by ModelRuntime's
 * read-modify-write OAuth refresh path.  The lock file contains no credential
 * data and is removed in a finally block.
 */
async function acquireFileLock(filePath: string, options: FileLockOptions): Promise<LockRelease> {
  await ensureSecureDirectory(filePath);
  const lockPath = `${filePath}.lock`;
  const startedAt = Date.now();

  while (true) {
    try {
      const handle = await open(lockPath, "wx", AUTH_FILE_MODE);
      const metadata: LockMetadata = {
        ownerId: randomUUID(),
        pid: process.pid,
        acquiredAt: Date.now(),
      };
      await handle.writeFile(JSON.stringify(metadata), "utf8");
      await handle.close();
      await chmod(lockPath, AUTH_FILE_MODE);
      let released = false;
      const heartbeat = setInterval(() => {
        if (released) return;
        void (async () => {
          try {
            const current = await readLockMetadata(lockPath);
            if (current?.ownerId !== metadata.ownerId) {
              clearInterval(heartbeat);
              return;
            }
            const now = new Date();
            await utimes(lockPath, now, now);
          } catch {
            clearInterval(heartbeat);
          }
        })();
      }, options.heartbeatMs);
      heartbeat.unref?.();
      return async () => {
        released = true;
        clearInterval(heartbeat);
        const current = await readLockMetadata(lockPath);
        if (current?.ownerId === metadata.ownerId) {
          await rm(lockPath, { force: true });
        }
      };
    } catch (error) {
      const code = typeof error === "object" && error !== null && "code" in error
        ? String(error.code)
        : "";
      if (code !== "EEXIST") throw error;

      // A crashed process must not strand the store forever.  Only reclaim a
      // lock that is older than the stale threshold; active locks are waited
      // on for a bounded period so a hung auth refresh fails safely.
      try {
        const lockStat = await stat(lockPath);
        const metadata = await readLockMetadata(lockPath);
        const stale = Date.now() - lockStat.mtimeMs > options.staleMs;
        // A live owner is never reclaimed solely because a refresh is slow;
        // heartbeat normally keeps mtime fresh, and PID validation is the
        // final guard against deleting an active lock.
        if (stale && (!metadata || !isProcessAlive(metadata.pid))) {
          await rm(lockPath, { force: true });
          continue;
        }
      } catch {
        // The owner may have released the lock between EEXIST and stat.
      }

      if (Date.now() - startedAt >= options.waitMs) {
        throw new Error("Auth storage is busy.");
      }
      await new Promise<void>((resolve) => setTimeout(resolve, 25));
    }
  }
}

/**
 * Product CredentialStore backed by Yishu/Auth/auth.json.  It is lazy: merely
 * constructing the runtime does not create an auth file; the first write
 * creates the 0700 directory and 0600 file.
 */
export class ProductCredentialStore implements YishuCredentialStore {
  readonly authPath: string;
  private readonly lockOptions: FileLockOptions;

  constructor(authPathOrOptions: string | ProductCredentialStoreOptions = YISHU_AUTH_PATH) {
    const options = typeof authPathOrOptions === "string" ? { authPath: authPathOrOptions } : authPathOrOptions;
    this.authPath = options.authPath ?? YISHU_AUTH_PATH;
    const staleMs = Math.max(10, options.lockStaleMs ?? DEFAULT_LOCK_STALE_MS);
    this.lockOptions = {
      staleMs,
      waitMs: Math.max(10, options.lockWaitMs ?? DEFAULT_LOCK_WAIT_MS),
      heartbeatMs: Math.max(5, Math.min(options.lockHeartbeatMs ?? DEFAULT_LOCK_HEARTBEAT_MS, Math.floor(staleMs / 2))),
    };
  }

  private async hardenExistingPath(): Promise<void> {
    if (!existsSync(this.authPath)) return;
    await chmod(path.dirname(this.authPath), AUTH_DIRECTORY_MODE);
    await chmod(this.authPath, AUTH_FILE_MODE);
  }

  async read(providerId: string): Promise<YishuCredential | undefined> {
    await this.hardenExistingPath();
    const data = await readCredentialMap(this.authPath);
    return data[providerId];
  }

  async list(): Promise<readonly YishuCredentialInfo[]> {
    await this.hardenExistingPath();
    const data = await readCredentialMap(this.authPath);
    return Object.entries(data).map(([providerId, credential]) => ({
      providerId,
      type: credential.type,
    }));
  }

  async modify(
    providerId: string,
    fn: (current: YishuCredential | undefined) => Promise<YishuCredential | undefined>,
  ): Promise<YishuCredential | undefined> {
    const release = await acquireFileLock(this.authPath, this.lockOptions);
    try {
      await cleanupStaleTemporaryFiles(this.authPath, this.lockOptions.staleMs);
      const data = await readCredentialMap(this.authPath);
      const next = await fn(data[providerId]);
      if (next === undefined) return data[providerId];
      data[providerId] = next;
      await writeCredentialMap(this.authPath, data);
      return next;
    } finally {
      await release();
    }
  }

  async delete(providerId: string): Promise<void> {
    const release = await acquireFileLock(this.authPath, this.lockOptions);
    try {
      await cleanupStaleTemporaryFiles(this.authPath, this.lockOptions.staleMs);
      const data = await readCredentialMap(this.authPath);
      delete data[providerId];
      await writeCredentialMap(this.authPath, data);
    } finally {
      await release();
    }
  }
}

/** In-memory implementation for tests; it never touches user auth paths. */
export class InMemoryCredentialStore implements YishuCredentialStore {
  private data: CredentialMap;
  private operation: Promise<void> = Promise.resolve();

  constructor(initial: CredentialMap = {}) {
    this.data = structuredClone(initial);
  }

  async read(providerId: string): Promise<YishuCredential | undefined> {
    return this.data[providerId];
  }

  async list(): Promise<readonly YishuCredentialInfo[]> {
    return Object.entries(this.data).map(([providerId, credential]) => ({
      providerId,
      type: credential.type,
    }));
  }

  async modify(
    providerId: string,
    fn: (current: YishuCredential | undefined) => Promise<YishuCredential | undefined>,
  ): Promise<YishuCredential | undefined> {
    let result: YishuCredential | undefined;
    const operation = this.operation.then(async () => {
      const next = await fn(this.data[providerId]);
      if (next !== undefined) this.data[providerId] = next;
      result = next ?? this.data[providerId];
    });
    this.operation = operation.catch(() => undefined);
    await operation;
    return result;
  }

  async delete(providerId: string): Promise<void> {
    const operation = this.operation.then(() => {
      delete this.data[providerId];
    });
    this.operation = operation.catch(() => undefined);
    await operation;
  }
}

export function createYishuCredentialStore(options?: ProductCredentialStoreOptions): ProductCredentialStore {
  return new ProductCredentialStore(options ?? YISHU_AUTH_PATH);
}

/**
 * Bound a server-side auth request without cancelling the underlying Pi
 * operation.  Logout deliberately continues after the wire request times
 * out: AuthService keeps its provider transition active until the real
 * operation settles, so a late credential deletion cannot race a new login.
 */
export type AuthWatchdogResult<T> =
  | { timedOut: true }
  | { timedOut: false; value: T };

export function runAuthWatchdog<T>(
  operation: Promise<T>,
  timeoutMilliseconds: number,
  onTimeout: () => void,
): Promise<AuthWatchdogResult<T>> {
  const duration = Number.isFinite(timeoutMilliseconds)
    ? Math.max(1, Math.floor(timeoutMilliseconds))
    : 30_000;

  return new Promise<AuthWatchdogResult<T>>((resolve, reject) => {
    let settled = false;
    const timer = setTimeout(() => {
      if (settled) return;
      settled = true;
      try {
        onTimeout();
      } catch {
        // A failed wire write must not turn the bounded request into an
        // unhandled rejection or release the underlying auth operation.
      }
      resolve({ timedOut: true });
    }, duration);

    // Attach both handlers immediately.  A late rejection after timeout is
    // intentionally consumed so a hung Pi operation cannot become an
    // unhandled process-level rejection.
    operation.then(
      (value) => {
        if (settled) return;
        settled = true;
        clearTimeout(timer);
        resolve({ timedOut: false, value });
      },
      (error: unknown) => {
        if (settled) return;
        settled = true;
        clearTimeout(timer);
        reject(error);
      },
    );
  });
}

export function resolveAuthWatchdogTimeoutMs(
  environment: NodeJS.ProcessEnv | Record<string, string | undefined> = process.env,
): number {
  const configured = Number(environment.YISHU_AUTH_WATCHDOG_MS);
  if (!Number.isFinite(configured) || configured < 1) return 30_000;
  return Math.min(Math.floor(configured), 300_000);
}

import { z } from "zod";

/**
 * Product-owned OAuth surface.  Pi may know about many more providers, but
 * only these two subscription paths are allowed to cross the Yishu runtime
 * boundary.  The local Grok proxy remains the default model route and is not
 * an OAuth provider here.
 */
export const AUTH_PROVIDER_IDS = ["openai-codex", "xai"] as const;
export type AuthProviderId = (typeof AUTH_PROVIDER_IDS)[number];
export const authProviderSchema = z.enum(AUTH_PROVIDER_IDS);

/**
 * Keep model exposure deliberately smaller than Pi's provider catalog.  These
 * IDs are product policy, not a promise that every future Pi model is exposed
 * to the desktop client.
 */
export const AUTH_CONTROLLED_MODEL_IDS = {
  "openai-codex": [
    "gpt-5.3-codex-spark",
    "gpt-5.4",
    "gpt-5.4-mini",
    "gpt-5.5",
    "gpt-5.6-luna",
    "gpt-5.6-sol",
    "gpt-5.6-terra",
  ],
  xai: ["grok-4.3", "grok-build-0.1", "grok-4.5"],
} as const satisfies Record<AuthProviderId, readonly string[]>;

export const authModelPreferenceSchema = z.discriminatedUnion("provider", [
  z.object({
    provider: z.literal("openai-codex"),
    model: z.enum(AUTH_CONTROLLED_MODEL_IDS["openai-codex"]),
  }).strict(),
  z.object({
    provider: z.literal("xai"),
    model: z.enum(AUTH_CONTROLLED_MODEL_IDS.xai),
  }).strict(),
]);
export type AuthModelPreference = z.infer<typeof authModelPreferenceSchema>;

export const authTypeSchema = z.literal("oauth");
export type AuthType = z.infer<typeof authTypeSchema>;

export const authStatusPayloadSchema = z.object({
  provider: authProviderSchema.optional(),
}).strict();

export const authLoginStartPayloadSchema = z.object({
  provider: authProviderSchema,
  // First product version is OAuth-only.  In particular, an ambient API key
  // must not silently turn either subscription provider into a configured one.
  authType: authTypeSchema,
}).strict();

export const authPromptReplyPayloadSchema = z.object({
  provider: authProviderSchema,
  promptId: z.string().uuid(),
  // OAuth manual codes are short-lived input.  The value is accepted only for
  // the pending interaction and is never copied to an event, trace, or log.
  value: z.string().max(4096),
}).strict();

export const authLoginCancelPayloadSchema = z.object({
  provider: authProviderSchema,
  reason: z.string().trim().min(1).max(200).optional(),
}).strict();

export const authLogoutPayloadSchema = z.object({
  provider: authProviderSchema,
}).strict();

export const authPublicModelSchema = z.object({
  provider: authProviderSchema,
  id: z.string().trim().min(1).max(160),
  name: z.string().trim().min(1).max(200),
}).strict();
export type AuthPublicModel = z.infer<typeof authPublicModelSchema>;

const PUBLIC_EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
const PUBLIC_NAME = /^[\p{L}\p{N}][\p{L}\p{N}._+\-@ ]{0,62}[\p{L}\p{N}.]$/u;
const BLOCKED_ACCOUNT_LABEL
  = /access[_-]?token|refresh[_-]?token|id[_-]?token|api[_-]?key|account[_-]?id|credential|authorization|password|secret|bearer|\btoken\b|jwt/i;
const LOOKS_LIKE_ACCOUNT_ID
  = /^(?:[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}|acct[_-]|user[_-]?id|org[_-]|sess[_-])/i;

/** Email or a short login name. Never a token, JWT, or provider account id. */
export function sanitizePublicAccountLabel(value: unknown): string | undefined {
  if (typeof value !== "string") return undefined;
  const text = value.trim();
  if (!text || text.length > 120) return undefined;
  if (BLOCKED_ACCOUNT_LABEL.test(text)) return undefined;
  if (/^eyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+$/.test(text)) return undefined;
  if (PUBLIC_EMAIL.test(text)) return text;
  if (LOOKS_LIKE_ACCOUNT_ID.test(text)) return undefined;
  if (PUBLIC_NAME.test(text)) return text;
  return undefined;
}

export const authPublicStatusSchema = z.object({
  provider: authProviderSchema,
  configured: z.boolean(),
  authType: authTypeSchema,
  models: z.array(authPublicModelSchema).max(16),
  requiresRelogin: z.boolean().optional(),
  /** Safe email or login name only. Never an account id or credential. */
  accountLabel: z.string().trim().min(1).max(120).refine(
    (value) => sanitizePublicAccountLabel(value) === value,
  ).optional(),
  /** xAI OAuth is a local Pi subscription bridge, not a stable direct API contract. */
  experimental: z.literal("experimental_local_subscription").optional(),
}).strict();
export type AuthPublicStatus = z.infer<typeof authPublicStatusSchema>;

export const authPromptSchema = z.discriminatedUnion("type", [
  z.object({
    type: z.literal("text"),
    message: z.string().trim().min(1).max(500),
    placeholder: z.string().max(200).optional(),
  }).strict(),
  z.object({
    type: z.literal("secret"),
    message: z.string().trim().min(1).max(500),
    placeholder: z.string().max(200).optional(),
  }).strict(),
  z.object({
    type: z.literal("select"),
    message: z.string().trim().min(1).max(500),
    options: z.array(z.object({
      id: z.string().trim().min(1).max(120),
      label: z.string().trim().min(1).max(200),
      description: z.string().max(500).optional(),
    }).strict()).max(16),
  }).strict(),
  z.object({
    type: z.literal("manual_code"),
    message: z.string().trim().min(1).max(500),
    placeholder: z.string().max(200).optional(),
  }).strict(),
]);
export type AuthPrompt = z.infer<typeof authPromptSchema>;

export const authFailureCodeSchema = z.enum([
  "cancelled",
  "invalid_request",
  "oauth_failed",
  "storage_failed",
  "relogin_required",
  "timeout",
  "unavailable",
]);
export type AuthFailureCode = z.infer<typeof authFailureCodeSchema>;

/**
 * These payload types are used by stdio-server and AuthService.  They are
 * intentionally separate from Pi's AuthEvent so Pi internals never become a
 * wire contract or accidentally carry credentials across the boundary.
 */
export type AuthInfoPayload = {
  provider: AuthProviderId;
  message: string;
  links?: readonly { url: string; label?: string }[];
};
export type AuthUrlPayload = {
  provider: AuthProviderId;
  url: string;
  instructions?: string;
};
export type AuthDeviceCodePayload = {
  provider: AuthProviderId;
  userCode: string;
  verificationUri: string;
  intervalSeconds?: number;
  expiresInSeconds?: number;
};
export type AuthProgressPayload = {
  provider: AuthProviderId;
  message: string;
};
export type AuthPromptPayload = {
  provider: AuthProviderId;
  promptId: string;
  prompt: AuthPrompt;
};
export type AuthFailurePayload = {
  provider: AuthProviderId;
  code: AuthFailureCode;
  message: string;
};
